        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; ++i) {
                TreeNode cur = queue.poll();
                ans.add(cur.value);
                if (cur.children != null) {
                    for (TreeNode child : cur.children) {
                        queue.add(child);
                    }
                }
            }
        }

        return ans;
    }
}
